import {parseAdminCSV,adminCSV,adminTemplate} from './admin-csv.mjs';
export function createAdminUI({e,actor,render,toast,refresh,dirty}){
 let sequence=0,preview=null,csvRows=null,downloadURL=null,exportRows=[];
 const link=(label,p={})=>'<a href="#/admin?'+new URLSearchParams(p)+'">'+e(label)+'</a>',hidden=(k,v)=>'<input type="hidden" name="'+k+'" value="'+e(v)+'">',field=(label,k,v='',extra='')=>'<label class="vle-field">'+e(label)+'<input name="'+k+'" value="'+e(v)+'" '+extra+'></label>',area=(label,k,v='')=>'<label class="vle-field">'+e(label)+'<textarea name="'+k+'" maxlength="1000">'+e(v)+'</textarea></label>';
 async function api(path,data){const r=await fetch('/api/admin/'+path,{credentials:'same-origin',cache:'no-store',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error||'Admin operation failed.');return d;}
 const nav=tab=>'<nav class="vle-tabs" aria-label="Administration">'+[['overview','Overview'],['students','Students'],['staff','Staff'],['import','CSV import'],['audit','Change log'],['procedures','Procedures']].map(([k,t])=>'<a '+(tab===k?'aria-current="page"':'')+' href="#/admin?tab='+k+'">'+t+'</a>').join('')+'</nav>';
 function page(p){const token=++sequence;if(actor()?.role!=='report-reviewer')return'<p class="error">Administrator access required.</p>';queueMicrotask(()=>mount(p,token));return'<section class="vle"><div class="learning-section-title"><h1>Administration</h1><span>School data & accounts</span></div>'+nav(p.get('tab')||'overview')+'<div id="admin-content" aria-live="polite">Opening Administration…</div></section>';}
 async function mount(p,token){try{const tab=p.get('tab')||'overview';let html;if(p.get('id')||p.get('new'))html=await editor(p);else if(['students','staff'].includes(tab))html=await list(p,tab);else if(tab==='import')html=importPage();else if(tab==='audit'){const d=await api('audit');html='<section class="vle-panel"><h2>Recent admin changes</h2><p>Last 100 actions. Passwords and password hashes are never shown.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>When</th><th>Action</th><th>Record</th><th>Changed areas</th></tr></thead><tbody>'+d.rows.map(r=>'<tr><td>'+e(new Date(r.at).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'}))+'</td><td>'+e(r.action)+'</td><td>'+link(r.name,{tab:'students',id:r.personId})+'</td><td>'+e(r.fields.join(', ')||'Account credentials')+'</td></tr>').join('')+'</tbody></table></div>'+(!d.rows.length?'<p>No admin changes yet.</p>':'')+'</section>';}else if(tab==='procedures')html=procedures();else{const d=await api('dashboard');html='<div class="vle-grid">'+[['Active students',d.students,'students'],['Active staff',d.staff,'staff'],['Inactive or disabled logins',d.disabled,'students']].map(([t,n,v])=>'<article class="vle-panel"><h2>'+n+'</h2>'+link(t,{tab:v})+'</article>').join('')+'</div><section class="vle-panel"><h2>Data checks</h2><p>'+d.unallocated+' active students have no teaching groups. '+d.missingDOB+' active records have no birth date; '+d.missingEmail+' have no email.</p><p>New records can be prepared with login disabled. Add a password and review access before enabling an account. Disabling an account preserves its saved work.</p><div class="vle-actions">'+link('Add student',{tab:'students',new:'student'})+link('Add staff member',{tab:'staff',new:'staff'})+link('Import records',{tab:'import'})+'</div></section>';}if(token!==sequence||!document.querySelector('#admin-content'))return;document.querySelector('#admin-content').innerHTML=html;bind();}catch(err){if(token===sequence&&document.querySelector('#admin-content'))document.querySelector('#admin-content').innerHTML='<p class="error">'+e(err.message)+'</p>';}}
 async function list(p,tab){const kind=tab==='staff'?'staff':'student',q={kind,...Object.fromEntries(['search','cohort','status','offset'].filter(k=>p.get(k)).map(k=>[k,p.get(k)]))},d=await api('people?'+new URLSearchParams(q));exportRows=d.rows;return'<button class="btn" data-admin-export>Export this page CSV</button><div class="learning-section-title"><h2>'+d.total+' '+(kind==='staff'?(d.total===1?'staff record':'staff records'):(d.total===1?'student record':'student records'))+'</h2>'+link('＋ Add '+kind,{tab,new:kind})+'</div><form data-admin-filter class="community-filters">'+hidden('tab',tab)+'<label>Find<input name="search" aria-label="Find admin records" placeholder="Name, login, ID or email" value="'+e(q.search||'')+'" maxlength="120"></label>'+(kind==='student'?'<label>Form<select name="cohort" aria-label="Filter form group"><option value="">All groups</option>'+d.groups.map(g=>'<option value="'+e(g.id)+'" '+(q.cohort===g.id?'selected':'')+'>'+e(g.name)+'</option>').join('')+'</select></label>':'')+'<label>Status<select name="status"><option value="">All statuses</option>'+['Active','Inactive'].map(s=>'<option '+(q.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label><button class="btn">Find records</button>'+link('Clear filters',{tab})+'</form><div class="table-wrap admin-record-list"><table class="data-table"><thead><tr><th>Name</th><th>Form / role</th><th>Login</th><th>Record status</th><th>Account</th></tr></thead><tbody>'+d.rows.map(r=>'<tr><td>'+link(r.name,{tab,id:r.id})+'<br><small>'+e(r.schoolId)+'</small></td><td>'+e(r.groupName||r.jobTitle||r.area)+'</td><td>'+e(r.username)+'</td><td>'+e(r.status)+'</td><td>'+(r.accountEnabled?'Enabled':'Disabled')+'</td></tr>').join('')+'</tbody></table></div>'+(!d.total?'<p>No records match these filters.</p>':'')+'<div class="vle-actions">'+(d.offset?link('← Previous',{tab,...q,offset:d.offset-d.limit}):'')+(d.offset+d.limit<d.total?link('Next →',{tab,...q,offset:d.offset+d.limit}):'')+'</div>';}
 async function editor(p){let data;if(p.get('id'))data=await api('person?id='+encodeURIComponent(p.get('id')));else{const d=await api('people?kind='+encodeURIComponent(p.get('new')));data={...d,person:{kind:p.get('new')==='staff'?'staff':'student',status:'Active',accountEnabled:false,classes:[]}};}const r=data.person,student=r.kind==='student',tab=student?'students':'staff',groups=data.groups,selected=groups.find(g=>g.id===r.cohort);if(r.protected)return'<section class="vle-panel"><h2>Primary administrator</h2><p>The admin identity is protected so the school cannot lose its management login. Use this account to manage student and staff accounts.</p>'+link('Back to staff',{tab:'staff'})+'</section>';return'<p>'+link('← '+(student?'Students':'Staff'),{tab})+'</p><section class="vle-panel"><h2>'+e(r.id?r.name:'Add '+(student?'student':'staff member'))+'</h2><p>'+(r.id?'Stable internal ID: '+e(r.id)+' · Changes retain attendance, grades and Classroom work.':'A new stable ID will be generated. Accounts start disabled unless a password is set and access is enabled.')+'</p><form data-admin-save>'+hidden('id',r.id||'')+hidden('kind',r.kind)+hidden('expectedRevision',r.profileRevision||0)+'<div class="vle-form-grid">'+field('First name','firstName',r.firstName,'required maxlength="80"')+field('Last name','lastName',r.lastName,'required maxlength="100"')+field('Preferred name','preferredName',r.preferredName,'maxlength="80"')+field('Date of birth','dateOfBirth',r.dateOfBirth,'type="date"')+field('Email','email',r.email,'type="email" maxlength="160"')+field('Phone','phone',r.phone,'maxlength="100"')+(student?'<label class="vle-field">Form group<select name="cohort" data-admin-form-group required><option value="">Choose a form</option>'+groups.map(g=>'<option value="'+e(g.id)+'" '+(g.id===r.cohort?'selected':'')+'>'+e(g.name)+'</option>').join('')+'</select></label>':field('Job title','jobTitle',r.jobTitle,'maxlength="120"')+field('Curriculum / department','area',r.area,'maxlength="120"')+field('Phase','phase',r.phase,'maxlength="80"')+field('Usual room','usualRoom',r.usualRoom,'maxlength="100"'))+'</div><details><summary>Contact and enrolment details</summary>'+area('Address','address',r.address)+field('Languages (comma separated)','languages',r.languages,'maxlength="300"')+'<div class="vle-form-grid">'+field(student?'Enrolled on':'Employment start',student?'enrolledOn':'employmentStart',student?r.enrolledOn:r.employmentStart,'type="date"')+field('Left on (if applicable)','leftOn',r.leftOn,'type="date"')+'</div></details>'+(student?'<details><summary>Teaching groups · review when changing form</summary><p>Choose the actual subject groups, including option blocks. A form group alone does not assign subject options. Hold Ctrl (Windows) or Command (Mac) to select several groups.</p><label class="vle-field">Teaching groups<select name="classIds" multiple size="8" data-admin-teaching-groups aria-label="Student teaching groups">'+data.classes.map(c=>'<option data-year="'+e(c.year)+'" value="'+e(c.id)+'" '+(r.classes.includes(c.id)?'selected':'')+' '+(selected&&String(c.year)!==String(selected.year)?'disabled hidden':'')+'>'+e(c.name)+'</option>').join('')+'</select></label></details>':'<p>Teaching allocations and lesson placement are managed in <a href="#/timetable">Timetabling</a>. A newly created staff account initially has no allocated classes.</p>')+'<details open><summary>Account access</summary><div class="vle-form-grid">'+(student?'<p>Student login: <strong>'+e(r.username||'A six-digit number is generated on save')+'</strong>. Student login numbers remain stable.</p>':field('Username','username',r.username,'required pattern="[a-z][a-z0-9._-]{2,79}" maxlength="80" autocomplete="off"'))+'<label class="vle-field">Record status<select name="status">'+['Active','Inactive'].map(v=>'<option '+(r.status===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div><label class="admin-check"><input type="checkbox" name="accountEnabled" '+(r.accountEnabled?'checked':'')+'> Enable login</label>'+(!r.id?field('Initial password (optional; required to enable login)','password','','type="password" minlength="8" maxlength="128" autocomplete="new-password"'):'<p>Password last changed: '+e(r.passwordChangedAt?new Date(r.passwordChangedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'}):'Default demo password')+'</p>')+'</details><div class="vle-actions"><button class="btn primary">Save record</button>'+link('Cancel',{tab})+'</div></form></section>'+(r.id?'<details class="vle-panel"><summary>Set a new password</summary><p>The old password and existing sessions will stop working. This does not enable a disabled account.</p><form data-admin-password>'+hidden('id',r.id)+hidden('kind',r.kind)+hidden('expectedVersion',r.accountVersion)+'<div class="vle-form-grid">'+field('New password','password','','type="password" minlength="8" maxlength="128" required autocomplete="new-password"')+field('Confirm password','confirmation','','type="password" minlength="8" maxlength="128" required autocomplete="new-password"')+'</div><button class="btn primary">Set password</button></form></details>':'');}
 function importPage(){return'<section class="vle-panel"><h2>CSV input and validation</h2><p>Import up to 200 student or staff records. Existing records need their stable internal ID; blank ID creates a record. New imported accounts have login disabled until you set a password and enable access.</p><button class="btn" data-admin-template>Download template</button><form data-admin-import><label class="vle-field">CSV file<input type="file" data-admin-csv-file accept=".csv,text/csv"></label><label class="vle-field">CSV contents<textarea name="csv" rows="6" maxlength="500000" required placeholder="Use the template headers"></textarea></label><button class="btn primary">Validate and preview</button></form><div id="admin-import-preview"></div></section>';}
 function procedures(){return'<div class="vle-grid"><section class="vle-panel"><h2>Joiners</h2><ol><li>Add a student or staff record, or validate a CSV import.</li><li>Check name, form / department, dates and contact details.</li><li>Set a password, review account status and enable login.</li><li>Review student subject groups or staff teaching allocations before testing their timetable.</li></ol></section><section class="vle-panel"><h2>Changes and leavers</h2><p>Edit the existing stable ID instead of creating a duplicate. Review teaching groups when changing a student’s form. Set Inactive for leavers; disable login for temporary access suspension. Both retain history. Re-enable only after checking the record and enrolment.</p></section><section class="vle-panel"><h2>Roles and data access</h2><p>Admin: school-wide records and account management. Staff: allocated classes and existing MIS permissions. Students: their own Classroom work. Family accounts: linked children through the family portal.</p><p>New staff accounts have ordinary staff permissions. This workspace does not create extra administrators.</p></section><section class="vle-panel"><h2>Demo procedures</h2><p>Use fictional data. Saves and password changes stay in this browser and do not synchronise between testers. Passwords are hashed; they cannot be retrieved. Provide a newly set password to the tester yourself. No activation emails are sent.</p></section></div>';}
 function download(text,name){if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=downloadURL;a.download=name;a.click();}
 function bind(){const root=document.querySelector('#admin-content');root.querySelector('[data-admin-filter]')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/admin?'+new URLSearchParams([...new FormData(ev.currentTarget)].filter(([,v])=>v));});root.querySelectorAll('[data-admin-save],[data-admin-password]').forEach(f=>{f.addEventListener('input',()=>dirty(true));f.addEventListener('submit',async ev=>{ev.preventDefault();const b=ev.submitter;if(b.disabled)return;b.disabled=true;try{const d=Object.fromEntries(new FormData(f));d.expectedRevision=Number(d.expectedRevision);if(f.matches('[data-admin-save]')){d.accountEnabled=f.elements.accountEnabled.checked;if(d.kind==='student')d.classIds=[...f.elements.classIds.selectedOptions].map(o=>o.value);}const result=await api(f.matches('[data-admin-password]')?'password':'save',d);dirty(false);await refresh();toast(f.matches('[data-admin-password]')?'Password changed. Existing sessions revoked.':'Record saved.');const target='#/admin?'+new URLSearchParams({tab:d.kind==='staff'?'staff':'students',id:result.id});if(location.hash===target)render();else location.hash=target;}catch(err){toast(err.message);}finally{if(b.isConnected)b.disabled=false;}});});const group=root.querySelector('[data-admin-form-group]');group?.addEventListener('change',()=>{const options=[...group.options],label=options.find(o=>o.value===group.value)?.textContent||'',year=label.match(/Year\s*0?(\d+)/i)?.[1],select=root.querySelector('[data-admin-teaching-groups]');for(const o of select.options){const form=group.value,match=form.match(/^(fs[12]|\d+)/i),targetYear=match?(match[1].toLowerCase()==='fs1'?'FS1':match[1].toLowerCase()==='fs2'?'FS2':String(Number(match[1]))):year;const allowed=String(o.dataset.year)===String(targetYear);o.disabled=!allowed;o.hidden=!allowed;if(!allowed)o.selected=false;}});root.querySelector('[data-admin-export]')?.addEventListener('click',()=>download(adminCSV([['id','kind','firstName','lastName','email','phone','dateOfBirth','cohort','username'],...exportRows.map(p=>[p.id,p.kind,p.firstName,p.lastName,p.email,p.phone,p.dateOfBirth,p.cohort,p.kind==='staff'?p.username:''])]),'WIST-admin-records.csv'));root.querySelector('[data-admin-template]')?.addEventListener('click',()=>download(adminTemplate(),'WIST-admin-import-template.csv'));root.querySelector('[data-admin-csv-file]')?.addEventListener('change',async ev=>{const file=ev.target.files[0];if(file){if(file.size>500000){toast('Use a CSV file smaller than 500 KB.');return;}root.querySelector('[name="csv"]').value=await file.text();preview=null;csvRows=null;root.querySelector('#admin-import-preview').innerHTML='';}});root.querySelector('[data-admin-import]')?.addEventListener('input',()=>{preview=null;csvRows=null;root.querySelector('#admin-import-preview').innerHTML='';});root.querySelector('[data-admin-import]')?.addEventListener('submit',async ev=>{ev.preventDefault();try{csvRows=parseAdminCSV(ev.currentTarget.elements.csv.value);preview=await api('import-preview',{rows:csvRows});const panel=root.querySelector('#admin-import-preview');panel.innerHTML='<h3>Import preview</h3>'+preview.errors.map(r=>'<p class="error">Row '+r.row+': '+e(r.message)+'</p>').join('')+'<div class="table-wrap"><table class="data-table"><thead><tr><th>Row</th><th>Action</th><th>Name</th><th>Login</th></tr></thead><tbody>'+preview.preview.map(r=>'<tr><td>'+r.row+'</td><td>'+e(r.action)+'</td><td>'+e(r.name)+'</td><td>'+e(r.username)+'</td></tr>').join('')+'</tbody></table></div>'+(!preview.errors.length?'<button class="btn primary" data-admin-import-confirm>Import '+preview.preview.length+' '+(preview.preview.length===1?'record':'records')+'</button>':'<p>Fix all errors and preview again. Nothing has been saved.</p>');panel.querySelector('[data-admin-import-confirm]')?.addEventListener('click',async ev=>{ev.target.disabled=true;try{const result=await api('import-commit',{rows:csvRows,expectedRevision:preview.expectedRevision,revisions:preview.revisions});await refresh();toast(result.changed+' '+(result.changed===1?'record imported.':'records imported.'));preview=null;csvRows=null;render();}catch(err){toast(err.message);ev.target.disabled=false;}});}catch(err){toast(err.message);}});}
 return{page};
}
